package com.example.smartdining;
import android.app.Activity;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.Gravity;import android.view.View;import android.view.ViewGroup;import android.widget.BaseAdapter;import android.widget.LinearLayout;import android.widget.TextView;import java.util.List;
public class HotelRowAdapter extends BaseAdapter {private final Activity a;private final List<String> names,addresses;private final List<Integer> ids;public HotelRowAdapter(Activity a,List<String> n,List<String> ad,List<Integer> i){this.a=a;names=n;addresses=ad;ids=i;}public int getCount(){return names.size();}public Object getItem(int p){return names.get(p);}public long getItemId(int p){return p;}public View getView(int p,View cv,ViewGroup parent){LinearLayout card=new LinearLayout(a);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(18,16,18,16);card.setGravity(Gravity.CENTER_VERTICAL);GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(20);bg.setStroke(1,Color.rgb(225,232,239));card.setBackground(bg);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,5,0,5);card.setLayoutParams(cp);TextView title=new TextView(a);title.setText(names.get(p));title.setTextColor(Color.rgb(23,50,77));title.setTextSize(17);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);card.addView(title);TextView sub=new TextView(a);sub.setText((addresses.size()>p?addresses.get(p):"")+"\nTap to explore menu  ›");sub.setTextColor(Color.rgb(92,109,126));sub.setTextSize(13);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=AppChrome.dp(a,4);card.addView(sub,sp);return card;}}
